'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'true'

  cookieStore.set(NOTIFICATIONS_COOKIE, String(!notificationsEnabled), {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
  })

  // Re-render the current route after the mutation without navigating away.
  refresh()
}

--- page ---
import { cookies } from 'next/headers'

import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get('notifications-enabled')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'on' : 'off'}</strong>.
      </p>

      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

